// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address sender, address target, uint256 amount, bytes calldata data) public {
        vm.assume(sender != c.owner());
        vm.assume(amount <= address(c).balance);
        vm.deal(address(c), amount);
        bool ok;
        vm.prank(sender);
        try c.sendMoney(target, amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
